export const source22ExistingViaLayerRequirements:Readonly<Record<string,readonly ("inner1"|"inner2")[]>> = {"INPUT_FAULT_ESCAPE_VIA":["inner1","inner2"],"TEC_CLEAR_RESISTOR_ENTRY":["inner1"],"MCU_ARM_MCU_ENTRY":["inner1"],"FAULT_SUPERVISOR_TRANSFER":["inner1"],"PD_VALID_BIAS_ENTRY":["inner1"]}
export function attachSource22LayerPorts(via:Via|null,layers:readonly ("inner1"|"inner2")[]) {
  if (!via) return
  for (const layer of layers) {
    if (via.children.some(child=>child instanceof Port && child.getNameAndAliases().includes(layer))) continue
    const port = new Port({name:layer,layer})
    port.registerMatch(via)
    via.add(port)
  }
}
export function attachSource22ExistingViaLayers(via:Via|null) {
  if (!via) return
  const name=via.getNameAndAliases().find(name=>source22ExistingViaLayerRequirements[name])
  if (name) attachSource22LayerPorts(via,source22ExistingViaLayerRequirements[name])
}
